import 'package:fit_store/features/auth/presentation/cubit/reset_password_cubit/reset_password_cubit.dart';import 'package:fit_store/features/auth/presentation/cubit/verify_email_cubit/verify_email_cubit.dart';import 'package:fit_store/features/auth/presentation/screens/on_boarding/on_boarding_screen.dart';import 'package:fit_store/features/auth/presentation/screens/otp/phone_otp_screen.dart';import 'package:fit_store/features/auth/presentation/screens/phone_number/phone_number_screen.dart';import 'package:fit_store/features/auth/presentation/screens/signup/verify_email.dart';import 'package:fit_store/features/auth/presentation/screens/splash_screen/splash_screen.dart';import 'package:fit_store/features/auth/presentation/screens/welcome/welcome_screen.dart';import 'package:fit_store/features/cart/screens/cart.dart';import 'package:fit_store/features/checkout/screens/checkout.dart';import 'package:fit_store/features/dashboard/course/screens/dashboard/coursesDashboard.dart';import 'package:fit_store/features/home/data/model/product_model.dart';import 'package:fit_store/features/home/domain/entities/categories_entity.dart';import 'package:fit_store/features/home/presentation/screens/home.dart';import 'package:fit_store/features/favourites/favourite.dart';  import 'package:flutter/material.dart';import 'package:fit_store/routes/routes.dart';import '../common/widgets/success_screen/success_screen.dart';import '../features/auth/presentation/screens/forget_password/forget_password_mail/forget_password_mail.dart';import '../features/auth/presentation/screens/forget_password/forget_password_mail/reset_password_screen.dart';import '../features/auth/presentation/screens/login/login_screen.dart';import '../features/auth/presentation/screens/signup/signup_screen.dart';import '../features/dashboard/ecommerce/screens/order/order.dart';import '../features/home/presentation/screens/sub_categories/sub_categories.dart';import '../features/store/domain/entities/brand_entity.dart';import '../features/store/presentation/screens/all_brands/all_brands.dart';import '../features/store/presentation/screens/all_brands/brand_products.dart';import '../features/store/presentation/screens/store.dart';import '../features/home/domain/entities/product_entity.dart';import '../features/home/presentation/screens/product_detail/product_detail.dart';import '../features/home/presentation/screens/product_reviews/product_reviews.dart'; import '../navigation_menu.dart';import '../personalization/presentation/screens/address/add_new_address.dart';import '../personalization/presentation/screens/address/user_address.dart';import '../personalization/presentation/screens/notification/notification_detail_screen.dart';import '../personalization/presentation/screens/notification/notification_screen.dart';import '../personalization/presentation/screens/profile/profile_screen.dart';class AppRoutes {  static Route<dynamic> onGenerateRoute(RouteSettings settings) {    switch (settings.name) {      case SplashScreen.routeName:        return MaterialPageRoute(          builder: (_) => const SplashScreen(),          settings: settings,        );      case WelcomeScreen.routeName:        return MaterialPageRoute(          builder: (_) => const WelcomeScreen(),          settings: settings,        );      case SignupScreen.routeName:        return MaterialPageRoute(          builder: (_) =>   SignupScreen(),          settings: settings,        );      case VerifyEmailScreen.routeName:        final email = settings.arguments as String;        return MaterialPageRoute(          builder: (_) => VerifyEmailScreen(            email: email,          ),          settings: settings,        );      case ResetPasswordScreen.routeName:        final email = settings.arguments as String;        return MaterialPageRoute(          builder: (_) => ResetPasswordScreen(            email: email,          ),          settings: settings,        );      case SuccessScreen.routeName:        final args = settings.arguments as Map<String, dynamic>? ?? {};        return MaterialPageRoute(          builder: (_) => SuccessScreen(            image: args['image'] as String,            title: args['title'] as String,            subTitle: args['subTitle'] as String,            onPressed: args['onPressed'] as void Function(BuildContext), // تحديث النوع هنا أيضاً          ),          settings: settings,        );      case OnBoardingScreen.routeName:        return MaterialPageRoute(          builder: (_) => const OnBoardingScreen(),          settings: settings,        );      case NavigationMenu.routeName:        return MaterialPageRoute(          builder: (_) =>   NavigationMenu(),          settings: settings,        );      case LoginScreen.routeName:        return MaterialPageRoute(          builder: (_) => const LoginScreen(),          settings: settings,        );      case TRoutes.coursesDashboard:        return MaterialPageRoute(          builder: (_) => const CoursesDashboard(),          settings: settings,        );      case TRoutes.home:        return MaterialPageRoute(          builder: (_) => const HomeScreen(),          settings: settings,        );      case StoreScreen.routeName:        return MaterialPageRoute(          builder: (_) => const StoreScreen(),          settings: settings,        );      case TRoutes.phoneSignIn:        return MaterialPageRoute(          builder: (_) => const PhoneNumberScreen(),          settings: settings,        );      case TRoutes.otpVerification:        return MaterialPageRoute(          builder: (_) => const PhoneOtpScreen(),          settings: settings,        );      // case TRoutes.reAuthenticateOtpVerification:      //   return MaterialPageRoute(      //     builder: (_) => const ReAuthenticatePhoneOtpScreen(),      //     settings: settings,      //   );      case ProductDetailScreen.routeName:        final product = settings.arguments as ProductEntity;        return MaterialPageRoute(          builder: (_) => ProductDetailScreen(product: product,),          settings: settings,        );      case BrandProducts.routeName:        final brand = settings.arguments as BrandEntity;        return MaterialPageRoute(          builder: (_) => BrandProducts(brand: brand,),          settings: settings,        );      case TRoutes.profileScreen:        return MaterialPageRoute(          builder: (_) => const ProfileScreen(),          settings: settings,        );      case TRoutes.cartScreen:        return MaterialPageRoute(          builder: (_) => const CartScreen(),          settings: settings,        );      case TRoutes.checkoutScreen:        return MaterialPageRoute(          builder: (_) => const CheckoutScreen(),          settings: settings,        );      case TRoutes.favouritesScreen:        return MaterialPageRoute(          builder: (_) => const FavouriteScreen(),          settings: settings,        );      case TRoutes.notification:        return MaterialPageRoute(          builder: (_) => const NotificationScreen(),          settings: settings,        );      case TRoutes.notificationDetails:        return MaterialPageRoute(          builder: (_) => const NotificationDetailScreen(),          settings: settings,        );      case ProductReviewsScreen.routeName:        final product = settings.arguments as ProductEntity;        return MaterialPageRoute(          builder: (_) => ProductReviewsScreen(product: product),          settings: settings,        );      case AddNewAddressScreen.routeName:        return MaterialPageRoute(          builder: (_) => const AddNewAddressScreen(),          settings: settings,        );      case UserAddressScreen.routeName:        return MaterialPageRoute(          builder: (_) => const UserAddressScreen(),          settings: settings,        );      case SubCategoriesScreen.routeName:        final category = settings.arguments as CategoryEntity;        return MaterialPageRoute(          builder: (_) => SubCategoriesScreen(category: category,),          settings: settings,        );      case AllBrandsScreen.routeName:        return MaterialPageRoute(          builder: (_) => const AllBrandsScreen(),          settings: settings,        );      case ForgetPasswordMailScreen.routeName:        return MaterialPageRoute(          builder: (_) => const ForgetPasswordMailScreen(),          settings: settings,        );      case OrderScreen.routeName:        return MaterialPageRoute(          builder: (_) => const OrderScreen(),          settings: settings,        );      default:        return MaterialPageRoute(          builder: (_) => const Scaffold(),          settings: settings,        );    }  }}